$$
\theta^ {\star} = \arg \min _ {\theta} \mathcal {L} _ {\mathrm{SFT}} (\theta), \qquad \mathcal {L} _ {\mathrm{SFT}} (\theta) = - \mathbb {E} _ {(o _ {t - H + 1: t}, l, a _ {t}) \sim \mathcal {D} ^ {\mathrm{tar}}} \big [ \log \pi_ {\theta} (a _ {t} \mid o _ {t - H + 1: t}, l) \big ].\tag{1}
