$$
p _ {t, k} ^ {T} = \pi_ {T} ^ {(k)} (\cdot | o _ {\leq t}, \mathcal {I}, \hat {a} _ {<   t}), \quad p _ {t, k} ^ {S} = \pi_ {S} ^ {(k)} (\cdot | o _ {\leq t}, l, \hat {a} _ {<   t})\tag{4}
