$$

$$
\operatorname{JSD} \left(p ^ {T}, p ^ {S}\right) = \frac {1}{2} \operatorname{KL} \left(p ^ {T} \| m\right) + \frac {1}{2} \operatorname{KL} \left(p ^ {S} \| m\right), \quad m = \frac {1}{2} \left(p ^ {T} + p ^ {S}\right).\tag{6}
