$$
\tilde {A} _ {t} ^ {\mathrm{ref}} = \mu_ {\mathrm{int}} + \frac {\sigma_ {\mathrm{int}}}{\sigma_ {\mathrm{ref}} + \varepsilon} \big (\hat {A} _ {t} ^ {\mathrm{ref}} - \mu_ {\mathrm{ref}} \big),\tag{7}
