$$
\omega_ {t} = \mathrm{clip} \left(\frac {\hat {A} _ {t} ^ {\mathrm{mix}} - \mu_ {\mathrm{mix}}}{\sigma_ {\mathrm{mix}} + \varepsilon}, - c, c\right).\tag{9}
