$$
q _ {t, k} ^ {\star} = \arg \max _ {q \in \Delta (\mathcal {V} _ {k})} \left\{\mathbb {E} _ {u \sim q} \big [ r _ {t, k} (u) \big ] - \tau \operatorname{KL} \big (q \parallel p _ {t, k} ^ {\theta} (\cdot \mid h _ {t}) \big) \right\},\tag{11}
