$$
\mathcal {L} _ {\mathrm{AGD}} = \mathbb {E} _ {\hat {\tau}} \left[ \frac {1}{T K} \sum_ {t = 1} ^ {T} \sum_ {k = 1} ^ {K} \mathrm{KL} \big (q _ {t, k} ^ {\star} \| p _ {t, k} ^ {\theta} \big) \right].\tag{12}
