$$
\bar {r} _ {t} (a) = \sum_ {k = 1} ^ {K} \Bigl (r _ {t, k} (a _ {k}) - \mathbb {E} _ {v \sim p _ {t, k} ^ {\theta} (\cdot | a _ {<   k}, h _ {t})} \bigl [ r _ {t, k} (v) \bigr ] \Bigr).\tag{13}
