$$
D _ {t} ^ {\mathrm{dist}} (h _ {t}) = \mathrm{KL} \left(q _ {t} ^ {\star} (\cdot | h _ {t}) \| \pi_ {\theta^ {\prime}} (\cdot | h _ {t})\right).\tag{15}
